1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns a new owner's customer code before it is saved. The sequence is per-city: one
9	 * more than the number of owners already in this owner's city (see {@link Cities#matches}).
10	 */
11	public class AssignCustomerCode {
12	
13	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
14	        int sequence = countInCity(owner, ownerRepository) + 1;
15	        owner.setCustomerCode(CustomerCode.format(owner.getCity(), owner.getLastName(), sequence));
16	    }
17	
18	    private static int countInCity(Owner owner, OwnerRepository ownerRepository) {
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (Cities.matches(existing, owner.getCity())) {
22	                count++;
23	            }
24	        }
25	        return count;
26	    }
27	}
