1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Formats an owner's customer code as {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3}
7	 * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first
8	 * three letters of the last name and {@code NNNN} a 4-digit zero-padded sequence number
9	 * (e.g. {@code LON-SMI-0007}).
10	 */
11	final class CustomerCode {
12	
13	    private CustomerCode() {
14	    }
15	
16	    static String format(String city, String lastName, int sequence) {
17	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
18	    }
19	
20	    private static String prefix(String value) {
21	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
22	    }
23	}
