1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.CityRegion;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * The upper-cased first letters of the first and last name, dot-separated with a
32	     * trailing dot, e.g. {@code J.S.}.
33	     */
34	    default String initials(Owner owner) {
35	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
36	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
37	    }
38	
39	    /**
40	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
41	     * {@code YY} is the last two digits of the registration date year, e.g.
42	     * {@code SMI-0007-M26}.
43	     */
44	    default String membershipNumber(Owner owner) {
45	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
46	        return owner.getCustomerCode() + "-M" + yy;
47	    }
48	
49	    /**
50	     * The owner's membership tier: {@code SILVER} when the owner has no namesakes
51	     * ({@code namesakeCount} is 0) and an email address is present, otherwise
52	     * {@code BRONZE}.
53	     */
54	    default String membershipTier(Owner owner) {
55	        boolean noNamesakes = Integer.valueOf(0).equals(owner.getNamesakeCount());
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
57	        return noNamesakes && hasEmail ? "SILVER" : "BRONZE";
58	    }
59	
60	    /**
61	     * The canonical region derived from the owner's city via the pinned city-to-region
62	     * table, or {@code UNKNOWN} when the city is not in the table.
63	     */
64	    default String locality(Owner owner) {
65	        return CityRegion.localityOf(owner.getCity());
66	    }
67	
68	    Owner toOwner(OwnerDto ownerDto);
69	
70	    @Mapping(target = "id", ignore = true)
71	    @Mapping(target = "pets", ignore = true)
72	    @Mapping(target = "customerCode", ignore = true)
73	    @Mapping(target = "householdId", ignore = true)
74	    @Mapping(target = "namesakeCount", ignore = true)
75	    Owner toOwner(OwnerFieldsDto ownerDto);
76	
77	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
78	
79	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
80	
81	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
82	        OwnerPageDto ownerPageDto = new OwnerPageDto();
83	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
84	        ownerPageDto.setPage(ownerPage.getNumber());
85	        ownerPageDto.setSize(ownerPage.getSize());
86	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
87	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
88	        return ownerPageDto;
89	    }
90	}
