10	 * the current day. Existing owners are counted by their {@link Owner#getRegistrationDate()
11	 * registrationDate}, matching the date a new owner defaults to (see {@link DefaultRegistrationDate}),
12	 * so a full day cannot grow further.
13	 */
14	public class EnsureDailyLimit {
15	
16	    /** Maximum number of owners allowed per day; the next create once reached is rejected. */
17	    static final int MAX_OWNERS_PER_DAY = 100;
18	
19	    public void service(OwnerRepository ownerRepository) throws DailyLimitReachedException {
20	        LocalDate today = LocalDate.now();
21	        int count = 0;
22	        for (Owner owner : ownerRepository.findAll()) {
23	            if (today.equals(owner.getRegistrationDate())) {
24	                count++;
25	            }
26	        }
27	        if (count >= MAX_OWNERS_PER_DAY) {
28	            throw new DailyLimitReachedException(today);
29	        }
30	    }
31	}
